using System.Collections.ObjectModel;
using System.Globalization;
using System.Windows;
using System.Windows.Controls;
using CommerceErp.Core;
namespace CommerceErp.Desktop;
public sealed class ManualOrderLine
{public string ProductId{get;set;}="";public string VariantId{get;set;}="";public decimal Quantity{get;set;}=1;public decimal GoodsAmount{get;set;}public decimal Discount{get;set;}}
public sealed class ManualOrderWindow:Window
{
    private readonly TextBox _productSearch=new();private readonly ComboBox _product=new(){DisplayMemberPath="Label"};
    private readonly LocalApiClient _api;private WorkspaceProfile? _workspace;private readonly ComboBox _shop=new(){DisplayMemberPath="Name"};private readonly TextBox _number=new(),_shipping=new(){Text="0"},_discount=new(){Text="0"},_paid=new(){Text="0"};private readonly TextBlock _error=new(){TextWrapping=TextWrapping.Wrap};private readonly DataGrid _grid=new(){AutoGenerateColumns=false,CanUserAddRows=true,CanUserDeleteRows=true,IsReadOnly=false};public ObservableCollection<ManualOrderLine> Lines{get;}=[];public SampleOrder? Order{get;private set;}
    public ManualOrderWindow(LocalApiClient api){_api=api;Title="人工订单录入";FontFamily=new System.Windows.Media.FontFamily("Microsoft YaHei UI");FontSize=13;Width=1040;Height=820;MinWidth=850;MinHeight=760;WindowStartupLocation=WindowStartupLocation.CenterOwner;var root=new DockPanel{Margin=new Thickness(20),Background=System.Windows.Media.Brushes.White};Content=root;var top=new StackPanel();DockPanel.SetDock(top,Dock.Top);root.Children.Add(top);top.Children.Add(new TextBlock{Text="人工订单录入",FontSize=22,FontWeight=FontWeights.SemiBold,Margin=new Thickness(0,0,0,10)});void Field(string title,Control field){top.Children.Add(new TextBlock{Text=title,Margin=new Thickness(0,6,0,3)});top.Children.Add(field);}Field("店铺（仅显示已授权且启用的店铺）",_shop);Field("外部订单号",_number);Field("商品搜索（编码、名称或平台规格；每次最多显示50条）",_productSearch);var search=new Button{Content="搜索商品"};search.Click+=async(_,_)=>{try{await LoadProducts();}catch(Exception e){_error.Text=e.Message;}};top.Children.Add(search);Field("选择已映射商品（新增行后填写数量与金额）",_product);var add=new Button{Content="加入明细",Margin=new Thickness(0,6,0,0)};add.Click+=(_,_)=>{if(_product.SelectedItem is ProductChoice c)Lines.Add(new(){ProductId=c.Mapping.PlatformProductId,VariantId=c.Mapping.PlatformSkuId});};top.Children.Add(add);_shop.SelectionChanged+=async(_,_)=>{if(Lines.Count>0){Lines.Clear();_error.Text="切换店铺后已清空旧店铺明细，请重新选择商品。";}try{await LoadProducts();}catch(Exception e){_error.Text=e.Message;}};var amounts=new System.Windows.Controls.Primitives.UniformGrid{Columns=3,Margin=new Thickness(0,8,0,0)};foreach(var(title,box)in new[]{("运费（元）",_shipping),("整单优惠（元）",_discount),("实付（元）",_paid)}){var cell=new StackPanel{Margin=new Thickness(0,0,10,0)};cell.Children.Add(new TextBlock{Text=title,Margin=new Thickness(0,0,0,5)});cell.Children.Add(box);amounts.Children.Add(cell);}top.Children.Add(amounts);top.Children.Add(new TextBlock{Text="明细金额为该行总额，非单价；使用平台商品与规格标识匹配内部SKU。地址请在仓储发货页核实后保存。",TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,12,0,10)});var bottom=new StackPanel();DockPanel.SetDock(bottom,Dock.Bottom);root.Children.Add(bottom);bottom.Children.Add(_error);var submit=new Button{Content="提交订单并按当前设置审单",Margin=new Thickness(0,10,0,0)};submit.Click+=(_,_)=>{try{Order=Build();DialogResult=true;}catch(Exception e){_error.Text=e.Message;}};bottom.Children.Add(submit);foreach(var(c,b)in new[]{("平台商品ID","ProductId"),("平台SKU","VariantId"),("数量","Quantity"),("商品总额","GoodsAmount"),("行优惠","Discount")})_grid.Columns.Add(new DataGridTextColumn{Header=c,Binding=new System.Windows.Data.Binding(b),Width=new DataGridLength(1,DataGridLengthUnitType.Star)});_grid.ItemsSource=Lines;root.Children.Add(_grid);}
    public async Task LoadAsync(){_workspace=await _api.GetAsync<WorkspaceProfile>("/api/workspace");_shop.ItemsSource=_workspace.Shops.Where(x=>x.Enabled).ToList();_shop.SelectedIndex=0;await LoadProducts();}
    private async Task LoadProducts(){if(_shop.SelectedItem is not ShopProfile shop)return;var page=await _api.GetAsync<MasterPage<ProductChoice>>($"/api/catalog/products?shop={Uri.EscapeDataString(shop.Id)}&search={Uri.EscapeDataString(_productSearch.Text)}&size=50");if((_shop.SelectedItem as ShopProfile)?.Id!=shop.Id)return;_product.ItemsSource=page.Items;_product.SelectedIndex=0;}
    internal void FillDraft(string number,decimal paid){_number.Text=number;_paid.Text=paid.ToString(CultureInfo.InvariantCulture);}
    public SampleOrder Build(){if(!_grid.CommitEdit(DataGridEditingUnit.Cell,true)||!_grid.CommitEdit(DataGridEditingUnit.Row,true))throw new BusinessRuleException("请检查明细数字。");var shop=_shop.SelectedItem as ShopProfile??throw new BusinessRuleException("请选择可用店铺。");if(string.IsNullOrWhiteSpace(_number.Text)||Lines.Count==0||Lines.Count>200)throw new BusinessRuleException("订单号必填，明细须1–200行。");decimal Money(TextBox t){if(!decimal.TryParse(t.Text,NumberStyles.Number,CultureInfo.InvariantCulture,out var n)||n<0||decimal.Round(n,2)!=n)throw new BusinessRuleException("金额须为非负数，最多两位小数。");return n;}var shipping=Money(_shipping);var discount=Money(_discount);var paid=Money(_paid);if(Lines.Any(x=>string.IsNullOrWhiteSpace(x.ProductId)||string.IsNullOrWhiteSpace(x.VariantId)||x.Quantity<=0||decimal.Round(x.Quantity,3)!=x.Quantity||x.GoodsAmount<0||x.Discount<0||x.Discount>x.GoodsAmount||decimal.Round(x.GoodsAmount,2)!=x.GoodsAmount||decimal.Round(x.Discount,2)!=x.Discount))throw new BusinessRuleException("明细标识、数量或金额无效。");if(Lines.Sum(x=>x.GoodsAmount-x.Discount)+shipping-discount!=paid)throw new BusinessRuleException("实付必须等于明细总额减行优惠，加运费减整单优惠。");return new(){SchemaVersion=1,DataKind=_workspace!.Mode=="Business"?"manual":"synthetic",TenantId=_workspace.TenantId,Platform=shop.Platform,ShopId=shop.Id,ExternalOrderId=_number.Text.Trim(),SourceUpdatedAt=DateTimeOffset.UtcNow,PaymentState=PaymentState.Paid,FulfillmentState=FulfillmentState.Unfulfilled,Currency="CNY",ShippingFee=shipping,OrderDiscount=discount,PaidAmount=paid,Lines=Lines.Select((x,i)=>new SampleOrderLine{ExternalLineId="line-"+(i+1),PlatformProductId=x.ProductId.Trim(),PlatformSkuId=x.VariantId.Trim(),Quantity=x.Quantity,GoodsAmount=x.GoodsAmount,MerchantDiscount=x.Discount}).ToList()};}

}
